'use strict';
const ko="\n<section id=\"community\" class=\"community-page\" data-workspace-page=\"community\" aria-labelledby=\"community-title\" hidden>\n  <div class=\"wrap\">\n    <header class=\"community-hero\">\n      <p class=\"eyebrow\">K-DRUM · COMMUNITY</p>\n      <h1 id=\"community-title\">사용자 소통센터</h1>\n      <p>사용 중 궁금한 점과 개선 아이디어를 나누고, 유용한 답변을 함께 축적합니다.</p>\n    </header>\n    <div class=\"community-notice\" role=\"note\">\n      <strong>사용자 게시판 운영 중</strong>\n      <p>질문과 개선 의견은 GitHub Discussions에 등록할 수 있습니다. 게시글은 공개되며 작성하려면 GitHub 로그인이 필요합니다.</p>\n    </div>\n    <div class=\"community-actions\">\n      <a class=\"button primary community-forum-link\" href=\"https://github.com/YoungTeckHUR/KDRUM-Public/discussions\" target=\"_blank\" rel=\"noopener noreferrer\">사용자 게시판 열기 ↗</a>\n      <a class=\"community-welcome-link\" href=\"https://github.com/YoungTeckHUR/KDRUM-Public/discussions/92\" target=\"_blank\" rel=\"noopener noreferrer\">환영 공지 #92 읽기 ↗</a>\n    </div>\n    <div class=\"community-cards\" aria-label=\"소통 주제\">\n      <article class=\"community-card\"><span class=\"community-card-index\" aria-hidden=\"true\">01</span><h2>질문·답변</h2><p>모형 설치, 입력자료 준비, 모의 실행과 결과 해석</p></article>\n      <article class=\"community-card\"><span class=\"community-card-index\" aria-hidden=\"true\">02</span><h2>오류·개선 의견</h2><p>사용 과정의 불편사항, 재현 가능한 오류 및 개선 요청</p></article>\n      <article class=\"community-card\"><span class=\"community-card-index\" aria-hidden=\"true\">03</span><h2>기능 제안</h2><p>새로운 해석 기능, 활용 분야 및 기술 확산 아이디어</p></article>\n    </div>\n    <div class=\"community-details\">\n      <section aria-labelledby=\"community-how\">\n        <h2 id=\"community-how\">소통 운영 방식</h2>\n        <ol class=\"community-steps\">\n          <li><strong>사용자 의견 등록</strong><span>GitHub 계정으로 공개 질문 또는 의견을 작성합니다.</span></li>\n          <li><strong>개발진 확인·답변</strong><span>공개된 글을 검토하고 확인 가능한 범위에서 답변합니다.</span></li>\n          <li><strong>지식 공유·개선 검토</strong><span>주요 답변을 축적하고 필요하면 개선 과제로 연결합니다.</span></li>\n        </ol>\n      </section>\n      <aside class=\"community-safety\" aria-label=\"게시판 이용 안내\">\n        <h2>공개 게시판 이용 안내</h2>\n        <p>게시물은 작성 즉시 공개될 수 있으며, 사전 비공개 검수는 제공하지 않습니다. GitHub 로그인이 필요합니다.</p>\n        <p>이름·전화번호·이메일 등 개인정보와 미공개 유역자료, 내부 경로, 비공개 오류 로그, 운영 정보를 올리지 마세요.</p>\n        <p>답변은 연구개발 관련 정보 공유 목적이며 즉시 또는 개별 기술지원을 보장하지 않습니다.</p>\n        <a class=\"community-faq\" href=\"../seo-kdrum.html\">먼저 모형 소개·FAQ 확인하기 →</a>\n      </aside>\n    </div>\n  </div>\n</section>";
const en="\n<section id=\"community\" class=\"community-page\" data-workspace-page=\"community\" aria-labelledby=\"community-title\" hidden>\n  <div class=\"wrap\">\n    <header class=\"community-hero\">\n      <p class=\"eyebrow\">K-DRUM · COMMUNITY</p>\n      <h1 id=\"community-title\">User community</h1>\n      <p>Share questions and ideas, and build a reusable public knowledge base for K-DRUM.</p>\n    </header>\n    <div class=\"community-notice\" role=\"note\">\n      <strong>Community forum is open</strong>\n      <p>Post questions and improvement suggestions on GitHub Discussions. Posts are public and a GitHub account is required to contribute.</p>\n    </div>\n    <div class=\"community-actions\">\n      <a class=\"button primary community-forum-link\" href=\"https://github.com/YoungTeckHUR/KDRUM-Public/discussions\" target=\"_blank\" rel=\"noopener noreferrer\">Open the community forum ↗</a>\n      <a class=\"community-welcome-link\" href=\"https://github.com/YoungTeckHUR/KDRUM-Public/discussions/92\" target=\"_blank\" rel=\"noopener noreferrer\">Read welcome announcement #92 ↗</a>\n    </div>\n    <div class=\"community-cards\" aria-label=\"Community topics\">\n      <article class=\"community-card\"><span class=\"community-card-index\" aria-hidden=\"true\">01</span><h2>Questions & answers</h2><p>Installation, input preparation, simulations and interpretation</p></article>\n      <article class=\"community-card\"><span class=\"community-card-index\" aria-hidden=\"true\">02</span><h2>Bugs & feedback</h2><p>Usability issues, reproducible problems and improvement requests</p></article>\n      <article class=\"community-card\"><span class=\"community-card-index\" aria-hidden=\"true\">03</span><h2>Feature ideas</h2><p>New model capabilities, applications and technology sharing</p></article>\n    </div>\n    <div class=\"community-details\">\n      <section aria-labelledby=\"community-how\">\n        <h2 id=\"community-how\">How the community will work</h2>\n        <ol class=\"community-steps\">\n          <li><strong>Post a question or idea</strong><span>Use a GitHub account to publish a question or suggestion.</span></li>\n          <li><strong>Team review and reply</strong><span>The team may respond where public technical information is available.</span></li>\n          <li><strong>Share knowledge</strong><span>Reuse helpful answers and consider suggestions for future improvements.</span></li>\n        </ol>\n      </section>\n      <aside class=\"community-safety\" aria-label=\"Community posting guidance\">\n        <h2>Public discussion guidelines</h2>\n        <p>Posts can become visible immediately; there is no private pre-publication review. A GitHub account is required.</p>\n        <p>Do not post personal contact details, restricted basin data, private file paths, unpublished diagnostic logs or sensitive operational information.</p>\n        <p>Discussions are for research and knowledge exchange, not guaranteed individual technical support.</p>\n        <a class=\"community-faq\" href=\"seo-kdrum.html\">Read the model guide and FAQ first →</a>\n      </aside>\n    </div>\n  </div>\n</section>";
function render(lang){return lang==='ko'?ko:en;}
